pub fn fromError(cause: anyerror) ?[]const u8 {
    for (entries) |entry| if (entry.cause == cause) return entry.code;
    return null;
}
pub fn category(cause: anyerror) ?@import("transit_protocol").Diagnostic.Category {
    for (entries) |entry| if (entry.cause == cause) return entry.category;
    return null;
}
